let currentLang = 'gu';

function t(key) {
    if (!key) return '';
    if (I18N_DATA[currentLang] && I18N_DATA[currentLang][key]) {
        return I18N_DATA[currentLang][key];
    }
    if (I18N_DATA['en'] && I18N_DATA['en'][key]) {
        return I18N_DATA['en'][key];
    }
    if (I18N_DATA['gu'] && I18N_DATA['gu'][key]) {
        return I18N_DATA['gu'][key];
    }
    return key;
}

function setLanguage(lang) {
    if (!lang) return;
    currentLang = lang;
    try {
        localStorage.setItem('sos_lang', lang);
    } catch (e) {}

    // Update document attributes
    if (document.documentElement) {
        document.documentElement.lang = lang;
        document.documentElement.dir = (lang === 'ar') ? 'rtl' : 'ltr';
    }
    if (document.body) {
        document.body.dir = (lang === 'ar') ? 'rtl' : 'ltr';
    }

    // Apply translations to all DOM elements with data-i18n
    document.querySelectorAll('[data-i18n]').forEach(el => {
        const key = el.getAttribute('data-i18n');
        if (key === 'gpsFetching' && window.currentGpsLocked) {
            return;
        }
        const text = t(key);
        if (text) {
            if (el.tagName === 'INPUT' && (el.type === 'button' || el.type === 'submit')) {
                el.value = text;
            } else {
                el.innerText = text;
            }
        }
    });

    // Apply translations to placeholders
    document.querySelectorAll('[data-i18n-placeholder]').forEach(el => {
        const key = el.getAttribute('data-i18n-placeholder');
        const text = t(key);
        if (text) el.placeholder = text;
    });

    // Apply translations to tooltips / titles
    document.querySelectorAll('[data-i18n-title]').forEach(el => {
        const key = el.getAttribute('data-i18n-title');
        const text = t(key);
        if (text) el.title = text;
    });

    // Update page title if applicable
    if (document.title && document.title.includes("Sri Sri")) {
        document.title = `${t('appName')} - ${t('tagline')}`;
    }

    // Sync all dropdowns on the page
    document.querySelectorAll('.lang-select-box').forEach(sel => {
        sel.value = lang;
    });

    // Permanently neutralize any Google Translate banner or body shifts
    neutralizeGoogleTranslateBanner();

    // Broadcast custom event so dynamic UI (dashboards, charts) can react
    window.dispatchEvent(new CustomEvent('languageChanged', { detail: { lang } }));
}

// Voice Speech Synthesizer in current language
function speakInCurrentLanguage(text) {
    if (!('speechSynthesis' in window)) return;
    try {
        window.speechSynthesis.cancel();
        const utterance = new SpeechSynthesisUtterance(text);
        const langVoiceMap = {
            gu: 'gu-IN', hi: 'hi-IN', en: 'en-US', es: 'es-ES', fr: 'fr-FR',
            de: 'de-DE', ar: 'ar-SA', zh: 'zh-CN', ru: 'ru-RU', mr: 'mr-IN', ta: 'ta-IN'
        };
        utterance.lang = langVoiceMap[currentLang] || 'gu-IN';
        utterance.rate = 1.0;
        utterance.pitch = 1.0;
        window.speechSynthesis.speak(utterance);
    } catch (e) {
        console.warn("TTS speak failed:", e);
    }
}

// 🚀 PERMANENT ANTI-GOOGLE TRANSLATE BANNER NEUTRALIZER ("Google ni pati" removal)
function neutralizeGoogleTranslateBanner() {
    try {
        // Clear any old googtrans cookies that cause Google banner injection
        document.cookie = "googtrans=; expires=Thu, 01 Jan 1970 00:00:00 UTC; path=/;";
        document.cookie = "googtrans=; expires=Thu, 01 Jan 1970 00:00:00 UTC; domain=" + location.hostname + "; path=/;";

        // Enforce body position and top: 0
        if (document.body) {
            document.body.style.setProperty('top', '0px', 'important');
            document.body.style.setProperty('position', 'static', 'important');
            if (document.body.classList.contains('translated-ltr') || document.body.classList.contains('translated-rtl')) {
                document.body.classList.remove('translated-ltr', 'translated-rtl');
            }
        }
        if (document.documentElement) {
            document.documentElement.style.setProperty('top', '0px', 'important');
            if (document.documentElement.classList.contains('translated-ltr') || document.documentElement.classList.contains('translated-rtl')) {
                document.documentElement.classList.remove('translated-ltr', 'translated-rtl');
            }
        }

        // Hide and remove any google translate frames or elements
        const selectors = [
            '.goog-te-banner-frame',
            'iframe.goog-te-banner-frame',
            '.VIpgJd-ZVi9dl-OWXEXe-bYCrB',
            '.VIpgJd-ZVi9dl-OWXEXe-bYCrB-OEVmcd',
            '.VIpgJd-yAWneb-hvhGLG-j7EBfc',
            '#goog-gt-tt',
            '.goog-te-balloon-frame',
            '.goog-tooltip',
            '#google_translate_element',
            '.skiptranslate:not(.goog-te-combo)',
            'iframe[id^=":"]'
        ];
        document.querySelectorAll(selectors.join(', ')).forEach(el => {
            el.style.setProperty('display', 'none', 'important');
            el.style.setProperty('visibility', 'hidden', 'important');
            el.style.setProperty('height', '0px', 'important');
            el.style.setProperty('width', '0px', 'important');
            el.style.setProperty('opacity', '0', 'important');
            el.style.setProperty('pointer-events', 'none', 'important');
        });
    } catch (e) {}
}

// Auto-run on load
window.addEventListener('DOMContentLoaded', () => {
    let savedLang = 'gu';
    try {
        savedLang = localStorage.getItem('sos_lang') || 'gu';
    } catch (e) {}

    // Initial translation
    setLanguage(savedLang);

    // Bind all language selectors
    document.querySelectorAll('.lang-select-box').forEach(sel => {
        sel.value = currentLang;
        sel.addEventListener('change', (e) => {
            setLanguage(e.target.value);
        });
    });

    neutralizeGoogleTranslateBanner();
});

// Watch continuously and guard against any third-party top banner insertion
if (typeof window !== 'undefined') {
    const bannerObserver = new MutationObserver(() => {
        neutralizeGoogleTranslateBanner();
    });
    window.addEventListener('DOMContentLoaded', () => {
        neutralizeGoogleTranslateBanner();
        if (document.body) {
            bannerObserver.observe(document.body, { attributes: true, attributeFilter: ['style', 'class'] });
            bannerObserver.observe(document.documentElement, { childList: true, subtree: true });
        }
    });
    setInterval(neutralizeGoogleTranslateBanner, 500);
}
